</head>
<body>
  <div class="card">
    <div class="logo">
      <span style="font-size:26px">📊</span>
      <div>
        <div class="logo-text">BizOS</div>
        <div class="logo-sub">Gupta Electricals</div>
      </div>
    </div>
    <span class="draft-badge">⏳ DRAFT — Approval Pending</span>
    <h2>Invoice Review करें</h2>
    <p class="sub">नीचे details check करें और Approve या Reject करें।</p>

    <div class="detail-box">
      <div class="detail-row"><span class="detail-label">Invoice No.</span><span class="detail-value">__INVOICE_NO__</span></div>
      <div class="detail-row"><span class="detail-label">Customer</span><span class="detail-value">__CUSTOMER_NAME__</span></div>
      <div class="detail-row"><span class="detail-label">Invoice Date</span><span class="detail-value">__INVOICE_DATE__</span></div>
      <div class="detail-row"><span class="detail-label">Due Date</span><span class="detail-value">__DUE_DATE__</span></div>
    </div>

    <table class="items-table">
      <thead><tr><th>Description</th><th>Qty</th><th>Rate</th><th>Amount</th></tr></thead>
      <tbody>__ITEMS_ROWS__</tbody>
    </table>

    <div class="totals-box">
      <div class="total-row"><span>Taxable Amount</span><span>Rs __TAXABLE__</span></div>
      <div class="total-row"><span>CGST</span><span>Rs __CGST__</span></div>
      <div class="total-row"><span>SGST</span><span>Rs __SGST__</span></div>
      <div class="total-row grand"><span>Total Invoice</span><span>Rs __TOTAL__</span></div>
    </div>

    <div class="btn-row">
      <form action="/webhook/bizos-invoice-approve" method="POST" style="margin:0">
        <input type="hidden" name="invoice_id" value="__INVOICE_ID__">
