      </form>
      <form action="/webhook/bizos-invoice-reject" method="POST" style="margin:0">
        <input type="hidden" name="invoice_id" value="__INVOICE_ID__">
        <button type="submit" class="btn-reject">❌ Reject करें</button>
      </form>
    </div>

    <div class="footer">BizOS • Gupta Electricals • Powered by n8n</div>
  </div>
</body>
</html>
";

const invoiceId   = $("Insert Draft Invoice").item.json.id;
const invoiceNo   = $("Insert Draft Invoice").item.json.invoice_no;
const rawDate = $("Insert Draft Invoice").item.json.invoice_date;
const rawDue  = $("Insert Draft Invoice").item.json.due_date;
const invoiceDate = rawDate ? new Date(rawDate).toLocaleDateString('en-IN', {day:'2-digit',month:'2-digit',year:'numeric'}) : '';
const dueDate     = rawDue  ? new Date(rawDue).toLocaleDateString('en-IN', {day:'2-digit',month:'2-digit',year:'numeric'}) : '';
const taxable     = $("Insert Draft Invoice").item.json.taxable_amount;
const cgst        = $("Insert Draft Invoice").item.json.cgst;
const sgst        = $("Insert Draft Invoice").item.json.sgst;
const total       = $("Insert Draft Invoice").item.json.total;
const customerName = item.json.name;

const itemsJson = $("Normalize Submit").item.json.items_json || "[]";
let lineItems = [];
try { lineItems = JSON.parse(itemsJson); } catch(e) { lineItems = []; }

const itemRows = lineItems.map(it => {
  return "<tr><td>" + (it.desc||"") + "</td><td style="text-align:right">" + (it.qty||0) + "</td><td style="text-align:right">Rs " + Number(it.rate||0).toFixed(2) + "</td><td style="text-align:right;font-weight:600">Rs " + Number(it.amount||0).toFixed(2) + "</td></tr>";
}).join("");

const html = approvalHtml
  .replace(/__INVOICE_NO__/g, String(invoiceNo))
  .replace(/__CUSTOMER_NAME__/g, String(customerName))
  .replace(/__INVOICE_DATE__/g, String(invoiceDate))
  .replace(/__DUE_DATE__/g, String(dueDate))
  .replace(/__ITEMS_ROWS__/g, itemRows)
  .replace(/__TAXABLE__/g, String(taxable))
  .replace(/__CGST__/g, String(cgst))
  .replace(/__SGST__/g, String(sgst))
  .replace(/__TOTAL__/g, String(total))
  .replace(/__INVOICE_ID__/g, String(invoiceId));

return { json: { html } };

// Build Form HTML — inline HTML
const formHtml = "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>BizOS – New Sale Invoice</title>
  <style>
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; background: #f0f2f5; min-height: 100vh; display: flex; align-items: flex-start; justify-content: center; padding: 24px 16px; }
    .card { background: #fff; border-radius: 12px; box-shadow: 0 2px 12px rgba(0,0,0,0.1); padding: 28px; width: 100%; max-width: 640px; }
    .logo { display: flex; align-items: center; gap: 10px; margin-bottom: 20px; }
    .logo-text { font-size: 20px; font-weight: 700; color: #1a1a2e; }
    .logo-sub { font-size: 13px; color: #666; margin-top: 2px; }
    h2 { font-size: 17px; color: #1a1a2e; margin-bottom: 18px; padding-bottom: 12px; border-bottom: 1px solid #eee; }
    .row2 { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
    label { display: block; font-size: 12px; font-weight: 600; color: #555; margin-bottom: 5px; margin-top: 14px; text-transform: uppercase; letter-spacing: 0.4px; }
    select, input[type="text"], input[type="date"], input[type="number"] {
      width: 100%; padding: 9px 11px; border: 1.5px solid #e0e0e0; border-radius: 7px;
      font-size: 14px; color: #1a1a2e; background: #fafafa; transition: border-color 0.2s;
    }
    select:focus, input:focus { outline: none; border-color: #4f46e5; background: #fff; }

    /* Line items table */
    .items-section { margin-top: 20px; }
    .items-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px; }
    .items-header h3 { font-size: 14px; font-weight: 700; color: #1a1a2e; }
    .add-row-btn { padding: 6px 14px; background: #f0f0ff; color: #4f46e5; border: 1px solid #c7d2fe; border-radius: 6px; font-size: 13px; font-weight: 600; cursor: pointer; }
    .add-row-btn:hover { background: #e0e7ff; }
    .items-table { width: 100%; border-collapse: collapse; font-size: 13px; }
    .items-table th { text-align: left; padding: 8px 6px; background: #f8f9ff; color: #555; font-size: 11px; text-transform: uppercase; letter-spacing: 0.4px; border-bottom: 2px solid #eee; }
    .items-table td { padding: 6px 4px; border-bottom: 1px solid #f0f0f0; vertical-align: middle; }
    .items-table input { padding: 7px 8px; border: 1px solid #e0e0e0; border-radius: 5px; background: #fafafa; font-size: 13px; }
    .items-table input:focus { outline: none; border-color: #4f46e5; background: #fff; }
    .items-table input[name="desc[]"] { width: 100%; min-width: 120px; }
    .items-table input[name="qty[]"] { width: 64px; text-align: right; }
    .items-table input[name="rate[]"] { width: 84px; text-align: right; }
    .items-table .line-total { width: 84px; text-align: right; font-weight: 600; color: #1a1a2e; padding-right: 8px; }
    .del-btn { width: 28px; height: 28px; background: #fff0f0; border: 1px solid #fecaca; border-radius: 5px; color: #ef4444; font-size: 16px; cursor: pointer; display: flex; align-items: center; justify-content: center; }
    .del-btn:hover { background: #fee2e2; }

    /* Totals */
    .totals-box { margin-top: 16px; background: #f8f9ff; border-radius: 8px; padding: 14px 16px; }
    .total-row { display: flex; justify-content: space-between; font-size: 14px; padding: 4px 0; color: #555; }
    .total-row.grand { font-weight: 700; font-size: 16px; color: #1a1a2e; border-top: 1px solid #ddd; margin-top: 6px; padding-top: 8px; }

    /* GST */
    .gst-row { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-top: 14px; }

    .btn-submit { width: 100%; margin-top: 24px; padding: 13px; background: #4f46e5; color: #fff; border: none; border-radius: 8px; font-size: 15px; font-weight: 600; cursor: pointer; }
    .btn-submit:hover { background: #4338ca; }
    .btn-submit:disabled { background: #a5b4fc; cursor: not-allowed; }
    .footer { margin-top: 16px; text-align: center; font-size: 12px; color: #aaa; }
  </style>
</head>
<body>
  <div class="card">
    <div class="logo">
      <span style="font-size:26px">📊</span>
      <div>
        <div class="logo-text">BizOS</div>
        <div class="logo-sub">Gupta Electricals</div>
      </div>
    </div>
    <h2>🧾 New Sale Invoice बनाएं</h2>

    <form id="invForm" action="/webhook/bizos-invoice-submit" method="POST">

      <!-- Customer + Invoice No -->
      <div class="row2">
        <div>
          <label for="customer_id">Customer *</label>
          <select id="customer_id" name="customer_id" required>
            <option value="">-- Customer चुनें --</option>
            __CUSTOMER_OPTIONS__
          </select>
        </div>
        <div>
          <label for="invoice_no">Invoice No. *</label>
          <input type="text" id="invoice_no" name="invoice_no" placeholder="जैसे: S-2001" required>
        </div>
      </div>

      <!-- Dates -->
      <div class="row2">
        <div>
          <label for="invoice_date">Invoice Date *</label>
          <input type="date" id="invoice_date" name="invoice_date" required>
        </div>
        <div>
          <label for="due_date">Due Date</label>
          <input type="date" id="due_date" name="due_date">
        </div>
      </div>

      <!-- Party GSTIN -->
      <label for="party_gstin">Customer GSTIN (Optional)</label>
      <input type="text" id="party_gstin" name="party_gstin" placeholder="15-character GSTIN" maxlength="15" style="text-transform:uppercase">

      <!-- Line items -->
      <div class="items-section">
        <div class="items-header">
          <h3>📦 Line Items</h3>
          <button type="button" class="add-row-btn" onclick="addRow()">+ Add Item</button>
        </div>
        <table class="items-table">
          <thead>
            <tr>
              <th>Description</th>
              <th>Qty</th>
              <th>Rate (Rs)</th>
              <th>Amount</th>
              <th></th>
            </tr>
          </thead>
          <tbody id="itemsBody">
            <!-- rows injected by JS -->
          </tbody>
        </table>
      </div>

      <!-- GST rates -->
      <div class="gst-row">
        <div>
          <label for="cgst_pct">CGST %</label>
          <input type="number" id="cgst_pct" name="cgst_pct" value="9" min="0" max="14" step="0.5" onchange="recalc()">
        </div>
        <div>
          <label for="sgst_pct">SGST %</label>
          <input type="number" id="sgst_pct" name="sgst_pct" value="9" min="0" max="14" step="0.5" onchange="recalc()">
        </div>
      </div>

      <!-- Hidden totals submitted with form -->
      <input type="hidden" id="h_taxable" name="taxable_amount" value="0">
      <input type="hidden" id="h_cgst" name="cgst" value="0">
      <input type="hidden" id="h_sgst" name="sgst" value="0">
      <input type="hidden" id="h_total" name="total" value="0">
      <!-- Line items as JSON -->
      <input type="hidden" id="h_items" name="items_json" value="[]">

      <!-- Totals display -->
      <div class="totals-box" id="totalsBox" style="display:none">
        <div class="total-row"><span>Taxable Amount</span><span id="d_taxable">Rs 0</span></div>
        <div class="total-row"><span>CGST</span><span id="d_cgst">Rs 0</span></div>
        <div class="total-row"><span>SGST</span><span id="d_sgst">Rs 0</span></div>
        <div class="total-row grand"><span>Total Invoice</span><span id="d_total">Rs 0</span></div>
      </div>

      <button type="submit" class="btn-submit" id="submitBtn">📋 Draft बनाएं (Owner Approval के लिए)</button>
    </form>
    <div class="footer">BizOS • Gupta Electricals • Powered by n8n</div>
  </div>

  <script>
    // Set today's date defaults
    const today = new Date().toISOString().split('T')[0];
    document.getElementById('invoice_date').value = today;
    const due = new Date(); due.setDate(due.getDate() + 15);
    document.getElementById('due_date').value = due.toISOString().split('T')[0];

    function fmt(n) { return 'Rs ' + Number(n).toLocaleString('en-IN', {minimumFractionDigits:2, maximumFractionDigits:2}); }

    function addRow(desc='', qty='', rate='') {
      const tbody = document.getElementById('itemsBody');
      const idx = tbody.children.length;
      const tr = document.createElement('tr');
      tr.innerHTML = `
        <td><input type="text" name="desc[]" placeholder="Item description" oninput="recalc()" value="${desc}"></td>
        <td><input type="number" name="qty[]" placeholder="1" min="0.01" step="0.01" oninput="recalc()" value="${qty}"></td>
        <td><input type="number" name="rate[]" placeholder="0.00" min="0" step="0.01" oninput="recalc()" value="${rate}"></td>
        <td class="line-total" id="lt_${idx}">Rs 0</td>
        <td><button type="button" class="del-btn" onclick="delRow(this)">×</button></td>`;
      tbody.appendChild(tr);
      recalc();
    }

    function delRow(btn) {
      btn.closest('tr').remove();
      recalc();
    }

    function recalc() {
      const qtyInputs = document.querySelectorAll('input[name="qty[]"]');
      const rateInputs = document.querySelectorAll('input[name="rate[]"]');
      const descInputs = document.querySelectorAll('input[name="desc[]"]');
      const cgstPct = parseFloat(document.getElementById('cgst_pct').value) || 0;
      const sgstPct = parseFloat(document.getElementById('sgst_pct').value) || 0;
      let taxable = 0;
      const items = [];
      for (let i = 0; i < qtyInputs.length; i++) {
        const qty = parseFloat(qtyInputs[i].value) || 0;
        const rate = parseFloat(rateInputs[i].value) || 0;
        const line = Math.round(qty * rate * 100) / 100;
        const ltEl = document.getElementById('lt_' + i);
        if (ltEl) ltEl.textContent = fmt(line);
        taxable += line;
        items.push({ desc: descInputs[i].value, qty, rate, amount: line });
      }
      const cgst = Math.round(taxable * cgstPct) / 100;
      const sgst = Math.round(taxable * sgstPct) / 100;
      const total = taxable + cgst + sgst;
      document.getElementById('d_taxable').textContent = fmt(taxable);
      document.getElementById('d_cgst').textContent = fmt(cgst);
      document.getElementById('d_sgst').textContent = fmt(sgst);
      document.getElementById('d_total').textContent = fmt(total);
      document.getElementById('h_taxable').value = taxable.toFixed(2);
      document.getElementById('h_cgst').value = cgst.toFixed(2);
      document.getElementById('h_sgst').value = sgst.toFixed(2);
      document.getElementById('h_total').value = total.toFixed(2);
      document.getElementById('h_items').value = JSON.stringify(items);
      document.getElementById('totalsBox').style.display = taxable > 0 ? 'block' : 'none';
    }

    document.getElementById('invForm').addEventListener('submit', function(e) {
      const items = JSON.parse(document.getElementById('h_items').value);
      if (items.length === 0 || items.every(it => it.amount === 0)) {
        e.preventDefault(); alert('कम से कम एक line item add करें।'); return;
      }
      if (parseFloat(document.getElementById('h_total').value) <= 0) {
        e.preventDefault(); alert('Total amount 0 नहीं हो सकता।'); return;
      }
      document.getElementById('submitBtn').disabled = true;
      document.getElementById('submitBtn').textContent = 'Saving...';
    });

    // Start with 2 empty rows
    addRow(); addRow();
  </script>
</body>
</html>
";

const options = items.map(it => {
  return '<option value="' + it.json.id + '">' + it.json.name + '</option>';
}).join('
');

const finalHtml = formHtml.replace('__CUSTOMER_OPTIONS__', options);
return [{ json: { html: finalHtml } }];
